/* Noise_NNpsk0_25519_ChaChaPoly_SHA256 conformance and interoperability tests.
 *
 * Two independent oracles are used:
 *   1. Pinned fixtures generated by tools/reference/noise_nnpsk0_reference.py,
 *      which re-implements the handshake in Python on top of hashlib and the
 *      `cryptography` package. Byte-for-byte agreement with those fixtures is
 *      an external check, not a self-consistency check.
 *   2. A minimal responder written directly against the Noise specification
 *      inside this file, used to drive the initiator through a full exchange
 *      with freshly generated ephemeral keys.
 */
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "esphome_noise.h"
#include "esphome_noise_crypto.h"
/* The shared responder that test_api_client also uses. It is a second implementation of
 * the same state machine, so putting it against the firmware's initiator here is a
 * cross-implementation check rather than a self-consistency one. */
#include "noise_test_responder.h"

static int failures;

#define CHECK(cond, ...)                                                                 \
    do {                                                                                 \
        if (!(cond)) {                                                                   \
            failures++;                                                                  \
            printf("FAIL %s:%d: ", __func__, __LINE__);                                  \
            printf(__VA_ARGS__);                                                         \
            printf("\n");                                                                \
        }                                                                                \
    } while (0)

static bool same(const uint8_t *a, const uint8_t *b, size_t n)
{
    return memcmp(a, b, n) == 0;
}

